const test = require('node:test');
const assert = require('node:assert');
const { isWithinLimit } = require('../src/size');

test('size limit in MiB', () => {
  assert.strictEqual(isWithinLimit(1024 * 1024, 1), true);
  assert.strictEqual(isWithinLimit(1024 * 1024 + 1, 1), false);
});
